3	namespace App\Services\Store;
4	
5	use App\Models\Core\Professional\Professional;
6	use App\Models\Retail\BrandTeamMembership;
7	
8	// V2: Core. Role-based access control for brand operations. 5 roles (owner, finance, marketing, analyst, read_only) with capability-based permission checks.
9	class BrandAccessService
10	{
11	    public const ROLE_OWNER = 'owner';
12	
13	    public const ROLE_FINANCE = 'finance';
14	
15	    public const ROLE_MARKETING = 'marketing';
16	
17	    public const ROLE_ANALYST = 'analyst';
18	
19	    public const ROLE_READ_ONLY = 'read_only';
20	
21	    public const CAPABILITY_ANALYTICS_NON_FINANCIAL_READ = 'analytics.non_financial.read';
22	
23	    public const CAPABILITY_ANALYTICS_FINANCIAL_READ = 'analytics.financial.read';
24	
25	    public const CAPABILITY_EXPORT_NON_FINANCIAL = 'export.non_financial';
26	
27	    public const CAPABILITY_EXPORT_FINANCIAL = 'export.financial';
28	
29	    public const CAPABILITY_STORE_MANAGE = 'store.manage';
30	
31	    public const CAPABILITY_SHOPIFY_MANAGE = 'shopify.manage';
32	
33	    /**
34	     * @var array<string, array<string, array{roles: array<int, string>, capabilities: array<int, string>}>>
35	     */
36	    private array $resolvedBrandAccessCache = [];
37	
38	    /**
39	     * @return array<int, string>
40	     */
41	    public function managedBrandIds(Professional $professional): array
42	    {
43	        return $this->brandIdsForCapability($professional, self::CAPABILITY_STORE_MANAGE);
44	    }
45	
46	    public function canManageBrand(Professional $professional, string $brandProfessionalId): bool
47	    {
48	        return $this->can($professional, $brandProfessionalId, self::CAPABILITY_STORE_MANAGE);
49	    }
50	
51	    public function canManageShopify(Professional $professional, string $brandProfessionalId): bool
52	    {
53	        return $this->can($professional, $brandProfessionalId, self::CAPABILITY_SHOPIFY_MANAGE);
54	    }
55	
56	    public function canReadBrandAnalytics(Professional $professional, string $brandProfessionalId): bool
57	    {
58	        return $this->can($professional, $brandProfessionalId, self::CAPABILITY_ANALYTICS_NON_FINANCIAL_READ);
59	    }
60	
61	    public function canReadBrandFinancialAnalytics(Professional $professional, string $brandProfessionalId): bool
62	    {
63	        return $this->can($professional, $brandProfessionalId, self::CAPABILITY_ANALYTICS_FINANCIAL_READ);
64	    }
65	
66	    /**
67	     * @return array<int, string>
68	     */
69	    public function brandIdsForCapability(Professional $professional, string $capability): array
70	    {
71	        $capability = mb_strtolower(trim($capability));
72	        if ($capability === '') {
73	            return [];
74	        }
75	
76	        $brandIds = [];
77	        foreach ($this->resolvedBrandAccess($professional) as $brandId => $access) {
78	            if (in_array($capability, $access['capabilities'], true)) {
79	                $brandIds[] = (string) $brandId;
80	            }
81	        }
82	
83	        return array_values(array_unique(array_filter($brandIds, static fn ($id): bool => is_string($id) && $id !== '')));
84	    }
85	
86	    public function can(Professional $professional, string $brandProfessionalId, string $capability): bool
87	    {
88	        $brandProfessionalId = trim($brandProfessionalId);
89	        if ($brandProfessionalId === '') {
90	            return false;
91	        }
92	
93	        $capability = mb_strtolower(trim($capability));
94	        if ($capability === '') {
95	            return false;
96	        }
97	
98	        $access = $this->resolvedBrandAccess($professional);
99	        if (! isset($access[$brandProfessionalId])) {
100	            return false;
101	        }
102	
103	        return in_array($capability, $access[$brandProfessionalId]['capabilities'], true);
104	    }
105	
106	    public function isBrandProfessional(Professional $professional): bool
107	    {
108	        return strtolower(trim((string) ($professional->professional_type ?? ''))) === 'brand';
109	    }
110	
111	    /**
112	     * @return array<string, array{roles: array<int, string>, capabilities: array<int, string>}>
113	     */
114	    private function resolvedBrandAccess(Professional $professional): array
115	    {
116	        $cacheKey = (string) $professional->id;
117	        if (isset($this->resolvedBrandAccessCache[$cacheKey])) {
118	            return $this->resolvedBrandAccessCache[$cacheKey];
119	        }
120	
121	        $rolesByBrand = [];
122	
123	        if ($this->isBrandProfessional($professional)) {
124	            $this->grantRole($rolesByBrand, (string) $professional->id, self::ROLE_OWNER);
125	        }
126	
127	        $teamMemberships = BrandTeamMembership::query()
128	            ->where('member_professional_id', $professional->id)
129	            ->where('status', 'active')
130	            ->get(['brand_professional_id', 'role']);
131	
132	        foreach ($teamMemberships as $membership) {
133	            $brandId = trim((string) $membership->brand_professional_id);
134	            $role = mb_strtolower(trim((string) $membership->role));
135	
136	            if ($brandId === '' || ! in_array($role, $this->teamRoles(), true)) {
137	                continue;
138	            }
139	
140	            $this->grantRole($rolesByBrand, $brandId, $role);
141	        }
142	
143	        $resolved = [];
144	        foreach ($rolesByBrand as $brandId => $roles) {
145	            $capabilities = [];
146	            foreach ($roles as $role) {
147	                $capabilities = [...$capabilities, ...$this->capabilitiesForRole($role)];
148	            }
149	
150	            $resolved[(string) $brandId] = [
151	                'roles' => array_values(array_unique(array_map('strval', $roles))),
152	                'capabilities' => array_values(array_unique(array_filter(array_map('strval', $capabilities)))),
153	            ];
154	        }
155	
156	        $this->resolvedBrandAccessCache[$cacheKey] = $resolved;
157	
158	        return $resolved;
159	    }
160	
161	    /**
162	     * @param  array<string, array<int, string>>  $rolesByBrand
163	     */
164	    private function grantRole(array &$rolesByBrand, string $brandProfessionalId, string $role): void
165	    {
166	        $brandProfessionalId = trim($brandProfessionalId);
167	        $role = mb_strtolower(trim($role));
168	
169	        if ($brandProfessionalId === '' || $role === '') {
170	            return;
171	        }
172	
173	        if (! isset($rolesByBrand[$brandProfessionalId])) {
174	            $rolesByBrand[$brandProfessionalId] = [];
175	        }
176	
177	        $rolesByBrand[$brandProfessionalId][] = $role;
178	    }
179	
180	    /**
181	     * @return array<int, string>
182	     */
183	    private function teamRoles(): array
184	    {
185	        return [
186	            self::ROLE_OWNER,
187	            self::ROLE_FINANCE,
188	            self::ROLE_MARKETING,
189	            self::ROLE_ANALYST,
190	            self::ROLE_READ_ONLY,
191	        ];
192	    }
193	
194	    /**
195	     * @return array<int, string>
196	     */
197	    private function capabilitiesForRole(string $role): array
198	    {
199	        $role = mb_strtolower(trim($role));
200	
201	        return match ($role) {
202	            self::ROLE_OWNER,
203	            self::ROLE_FINANCE => [
204	                self::CAPABILITY_ANALYTICS_NON_FINANCIAL_READ,
205	                self::CAPABILITY_ANALYTICS_FINANCIAL_READ,
206	                self::CAPABILITY_EXPORT_NON_FINANCIAL,
207	                self::CAPABILITY_EXPORT_FINANCIAL,
208	                self::CAPABILITY_STORE_MANAGE,
209	                self::CAPABILITY_SHOPIFY_MANAGE,
210	            ],
211	            self::ROLE_MARKETING => [
212	                self::CAPABILITY_ANALYTICS_NON_FINANCIAL_READ,
213	                self::CAPABILITY_EXPORT_NON_FINANCIAL,
214	                self::CAPABILITY_STORE_MANAGE,
215	            ],
216	            self::ROLE_ANALYST,
217	            self::ROLE_READ_ONLY => [
218	                self::CAPABILITY_ANALYTICS_NON_FINANCIAL_READ,
219	                self::CAPABILITY_ANALYTICS_FINANCIAL_READ,
220	                self::CAPABILITY_EXPORT_NON_FINANCIAL,
221	                self::CAPABILITY_EXPORT_FINANCIAL,
222	            ],
223	            default => [],
224	        };
225	    }
226	}
