299	    /**
300	     * Disconnect the brand's Shopify integration with a full server-side
301	     * sweep. Unlike a Shopify-initiated uninstall (where the token is
302	     * revoked BEFORE we hear about it), this runs while we still hold a
303	     * valid token, so we can delete:
304	     *   - The Side St Price automatic discount
305	     *   - The four Side St collections
306	     *   - Every sidest.* metafield definition (with values)
307	     *   - The Side St storefront access token
308	     *   - The Side St sales channel publication
309	     *   - Revoke the OAuth token itself
310	     *
311	     * Then locally:
312	     *   - Purge affiliate_product_selections scoped to this brand (any
313	     *     affiliate-curated lists become meaningless once the catalog is
314	     *     gone)
315	     *   - Delete the ProfessionalIntegration row
316	     *
317	     * Safe to call when no integration exists (returns success with an
318	     * empty teardown summary). Per-step failures in the Shopify sweep are
319	     * logged but don't abort the local cleanup — a brand who's already
320	     * uninstalled in Shopify still gets their local state cleared cleanly.
321	     */
322	    public function disconnect(Request $request): JsonResponse
323	    {
324	        $validator = Validator::make($request->all(), [
325	            'brand_professional_id' => ['sometimes', 'uuid'],
326	        ]);
327	
328	        if ($validator->fails()) {
329	            throw new ValidationException($validator);
330	        }
331	
332	        [$targetBrandId, $error] = $this->resolveTargetBrandProfessionalId(
333	            $request,
334	            isset($validator->validated()['brand_professional_id']) ? (string) $validator->validated()['brand_professional_id'] : null,
335	            true
336	        );
337	
338	        if ($error !== null) {
339	            return $error;
340	        }
341	
342	        $actorProfessional = $this->currentProfessional($request);
343	
344	        $integration = $this->currentShopifyIntegrationForBrand($targetBrandId);
345	
346	        $teardownSummary = null;
347	        if ($integration && ! empty($integration->access_token)) {
348	            try {
349	                $teardownSummary = $this->teardownService->teardownForIntegration($integration);
350	            } catch (\Throwable $e) {
351	                // The teardown service already logs per-step failures; this
352	                // catch only fires on a truly unexpected exception. We keep
353	                // going so the local disconnect still runs — leaving the
354	                // brand half-disconnected (Shopify side still present but
355	                // Side St thinks it's gone) is worse than orphaning a few
356	                // Shopify-side artifacts we can't re-reach.
357	                Log::error('Shopify teardown threw unexpectedly; continuing with local disconnect', [
358	                    'actor_professional_id' => (string) $actorProfessional->id,
359	                    'brand_professional_id' => $targetBrandId,
360	                    'error' => $e->getMessage(),
361	                ]);
362	            }
363	        }
364	
365	        // Affiliate curated selections only make sense while this brand has
366	        // a catalog to curate from. Blow them away so the affiliates don't
367	        // end up with dangling GIDs pointing at deleted products.
368	        $deletedSelections = AffiliateProductSelection::query()
369	            ->where('brand_professional_id', $targetBrandId)
370	            ->delete();
371	
372	        ProfessionalIntegration::query()
373	            ->where('professional_id', $targetBrandId)
374	            ->where('provider', ProfessionalIntegration::PROVIDER_SHOPIFY)
375	            ->delete();
376	
377	        // Clear all wizard progress and reset brand status so the setup wizard
378	        // starts fresh if the brand reconnects.
379	        BrandStoreSettings::clearWizardProgress($targetBrandId);
380	        BrandProfile::where('professional_id', $targetBrandId)
381	            ->update([
382	                'brand_status' => BrandStatus::Onboarding->value,
383	                'setup_complete' => false,
384	            ]);
385	
386	        Log::info('Shopify disconnected', [
387	            'actor_professional_id' => (string) $actorProfessional->id,
388	            'brand_professional_id' => $targetBrandId,
389	            'teardown_summary' => $teardownSummary,
390	            'deleted_selections' => $deletedSelections,
391	        ]);
392	
393	        return $this->success([
394	            'connected' => false,
395	            'brand_professional_id' => $targetBrandId,
396	            'teardown' => $teardownSummary,
397	            'selections_deleted' => $deletedSelections,
398	        ]);
399	    }
