560	    /**
561	     * Resolve a merchant-facing Shopify domain (custom primary domain or
562	     * raw handle) to the canonical `<handle>.myshopify.com` used by the
563	     * OAuth authorize flow.
564	     *
565	     *   mystore                     -> mystore.myshopify.com            (rewrite-only)
566	     *   mystore.myshopify.com       -> mystore.myshopify.com            (rewrite-only)
567	     *   https://mystore/admin       -> mystore.myshopify.com            (rewrite-only)
568	     *   radiorufus.com              -> <handle>.myshopify.com           (HTML discovery)
569	     *
570	     * The discovery path fetches the storefront HTML and matches a Shopify
571	     * storefront global that embeds the canonical shop URL. Most non-headless
572	     * Shopify themes still expose this — Hydrogen storefronts and heavily
573	     * stripped themes won't, so the caller must surface a clear fallback
574	     * error when we return null.
575	     *
576	     * Auth-gated (brand professionals + staff) because it lets us make
577	     * arbitrary outbound HTTP requests on behalf of the caller — an abuse
578	     * vector if left open.
579	     */
580	    public function resolveShop(Request $request): JsonResponse
581	    {
582	        $validator = Validator::make($request->query(), [
583	            'domain' => ['required', 'string', 'max:255'],
584	        ]);
585	
586	        if ($validator->fails()) {
587	            throw new ValidationException($validator);
588	        }
589	
590	        $raw = (string) $validator->validated()['domain'];
591	        $host = $this->stripDomainNoise($raw);
592	
593	        if ($host === '') {
594	            return $this->error('Enter a valid Shopify store domain.', 422);
595	        }
596	
597	        // Already a myshopify handle — no discovery needed.
598	        if (preg_match('/^([a-z0-9][a-z0-9-]*)\.myshopify\.com$/', $host, $m)) {
599	            return $this->success(['shop_domain' => "{$m[1]}.myshopify.com"]);
600	        }
601	
602	        // Bare handle (no dots) — assume the caller typed the myshopify handle
603	        // without the TLD and rewrite. This matches the frontend's shortcut UX.
604	        if (preg_match('/^[a-z0-9][a-z0-9-]*$/', $host)) {
605	            return $this->success(['shop_domain' => "{$host}.myshopify.com"]);
606	        }
607	
608	        // Anything else is a potential custom storefront domain — try to
609	        // discover the myshopify handle by scraping the homepage HTML.
610	        $discovered = $this->discoverShopifyHandle($host);
611	
612	        if ($discovered === null) {
613	            return $this->error(
614	                "Couldn't find a Shopify store at {$host}. Enter your myshopify.com URL instead (Shopify admin → Settings → Domains).",
615	                404
616	            );
617	        }
618	
619	        return $this->success(['shop_domain' => $discovered]);
620	    }
