622	    /**
623	     * Strip scheme, path, querystring, port, and lowercase — leaves just
624	     * the hostname. Returns '' when the input can't be coerced into a host.
625	     *
626	     * Implemented with explicit strpos calls instead of a single regex
627	     * because including `#` inside a `#`-delimited character class trips
628	     * PHP's PCRE parser ("Unknown modifier ']'"), and Laravel escalates
629	     * that warning to a 500. Plain string ops sidestep the ambiguity.
630	     */
631	    private function stripDomainNoise(string $raw): string
632	    {
633	        $host = strtolower(trim($raw));
634	        if ($host === '') {
635	            return '';
636	        }
637	
638	        // Strip scheme.
639	        if (str_starts_with($host, 'https://')) {
640	            $host = substr($host, 8);
641	        } elseif (str_starts_with($host, 'http://')) {
642	            $host = substr($host, 7);
643	        }
644	
645	        // Cut at the first boundary character — path, port, query, fragment.
646	        foreach ([':', '/', '?', '#'] as $boundary) {
647	            $pos = strpos($host, $boundary);
648	            if ($pos !== false) {
649	                $host = substr($host, 0, $pos);
650	            }
651	        }
652	
653	        return $host;
654	    }
