656	    /**
657	     * Reject private / link-local / loopback / multicast / reserved addresses
658	     * before issuing an outbound HTTP request. Prevents the resolveShop endpoint
659	     * from being abused as an SSRF probe against internal infrastructure.
660	     *
661	     * Accepts a host (IP literal or hostname). For hostnames, resolves all A
662	     * records and rejects if any resolved IP falls in a blocked range.
663	     */
664	    private function isPrivateHost(string $host): bool
665	    {
666	        $host = trim($host);
667	        if ($host === '') {
668	            return true;
669	        }
670	
671	        // If $host is a literal IP, just check it.
672	        if (filter_var($host, FILTER_VALIDATE_IP)) {
673	            return $this->ipIsBlocked($host);
674	        }
675	
676	        // Otherwise resolve and check every A record.
677	        $ips = gethostbynamel($host);
678	        if ($ips === false || empty($ips)) {
679	            // Non-resolvable — let the caller's Http::get error path handle it.
680	            return false;
681	        }
682	
683	        foreach ($ips as $ip) {
684	            if ($this->ipIsBlocked($ip)) {
685	                return true;
686	            }
687	        }
688	
689	        return false;
690	    }
691	
692	    private function ipIsBlocked(string $ip): bool
693	    {
694	        // NO_PRIV_RANGE  blocks 10/8, 172.16/12, 192.168/16, fc00::/7, fec0::/10
695	        // NO_RES_RANGE   blocks 0/8, 127/8, 169.254/16, 224/4, 240/4, ::1, fe80::/10
696	        $notPrivate = filter_var(
697	            $ip,
698	            FILTER_VALIDATE_IP,
699	            FILTER_FLAG_NO_PRIV_RANGE | FILTER_FLAG_NO_RES_RANGE
700	        );
701	
702	        return $notPrivate === false;
703	    }
704	
705	    /**
706	     * Fetch the storefront homepage and look for the embedded
707	     * `Shopify.shop = "<handle>.myshopify.com"` global that most themes
708	     * render inline. Returns the canonical shop domain or null.
709	     *
710	     * Network / parse failures are swallowed and translated into null —
711	     * the caller turns that into a user-facing 404.
712	     */
713	    private function discoverShopifyHandle(string $host): ?string
714	    {
715	        // SSRF guard: an authenticated brand can still probe internal infrastructure
716	        // via this endpoint. Rejecting private/link-local/loopback IPs blocks
717	        // metadata endpoints (169.254.169.254) and internal services without
718	        // breaking legitimate custom Shopify domains.
719	        if ($this->isPrivateHost($host)) {
720	            Log::info('Shopify resolveShop: rejected private/internal host', ['host' => $host]);
721	
722	            return null;
723	        }
724	
725	        $url = "https://{$host}/";
726	
727	        try {
728	            $response = Http::timeout(6)
729	                ->connectTimeout(4)
730	                // SSRF hardening: disable redirects. Without this, a public-IP
731	                // storefront could 302 to an internal host (e.g. 169.254.169.254)
732	                // and Guzzle would follow it — bypassing isPrivateHost above.
733	                ->withOptions(['allow_redirects' => false])
734	                ->withHeaders([
735	                    // Some Shopify storefronts block default PHP/curl user agents
736	                    // with a WAF rule. A real-browser UA sidesteps that without
737	                    // misrepresenting intent.
738	                    'User-Agent' => 'Mozilla/5.0 (compatible; SidestShopResolver/1.0)',
739	                    'Accept' => 'text/html,application/xhtml+xml',
740	                ])
741	                ->get($url);
742	        } catch (ConnectionException $e) {
743	            Log::info('Shopify resolveShop: connection failed', [
744	                'host' => $host,
745	                'error' => $e->getMessage(),
746	            ]);
747	
748	            return null;
749	        } catch (\Throwable $e) {
750	            Log::info('Shopify resolveShop: unexpected error', [
751	                'host' => $host,
752	                'error' => $e->getMessage(),
753	            ]);
754	
755	            return null;
756	        }
757	
758	        if (! $response->successful()) {
759	            return null;
760	        }
761	
762	        $body = (string) $response->body();
763	
764	        // Shopify themes commonly embed one of these:
765	        //   Shopify.shop = "foo.myshopify.com"
766	        //   "shop":"foo.myshopify.com"
767	        //   shop: "foo.myshopify.com"
768	        // All carry the canonical <handle>.myshopify.com; we take the first.
769	        $patterns = [
770	            '/Shopify\.shop\s*=\s*["\']([a-z0-9][a-z0-9-]*\.myshopify\.com)["\']/i',
771	            '/["\']shop["\']\s*:\s*["\']([a-z0-9][a-z0-9-]*\.myshopify\.com)["\']/i',
772	            '/([a-z0-9][a-z0-9-]*\.myshopify\.com)/i',
773	        ];
774	
775	        foreach ($patterns as $pattern) {
776	            if (preg_match($pattern, $body, $m)) {
777	                return strtolower($m[1]);
778	            }
779	        }
780	
781	        return null;
782	    }
783	}
